  'McClary y Massey 2023': { autores: 'McClary y Massey', titulo: 'Ankle Brachial Index', publicacion: 'StatPearls [Internet], NBK544226 (act. 2023-01-16)', doi: '', url: 'https://www.ncbi.nlm.nih.gov/books/NBK544226/', revision: { fecha: '2026-10', resultado: 'Sin cambios: el capítulo de StatPearls no se ha actualizado desde el 16 de enero de 2023 (fecha del documento en PubMed, consultada en 2026-10).' }, nota: 'Capítulo de StatPearls (NCBI Bookshelf); PDF aportado por el usuario. La clave lleva el año de la última actualización del capítulo. Razonamiento del cribado de rodilla.' },
  'McKeon 2008': { publicacion: 'Med Sci Sports Exerc 40(10):1810–1819', doi: '10.1249/mss.0b013e31817e0f92', revision: { fecha: '2026-10', resultado: 'Sin cambios en las cifras: PDF leído entero (2026-10). Se precisa en tp21 a qué tareas se aplican los niveles, las reglas de progresión y qué mejoró (FADI, FADI Sport, equilibrio con ojos cerrados, alcance posteromedial y posterolateral del SEBT) y qué no (equilibrio con ojos abiertos, alcance anterior); sin seguimiento ni medida de recidivas.' } },
  'McMordie 2023': { autores: 'McMordie, Viswanathan y Gillis', titulo: 'Cervical Spine Fractures Overview', publicacion: 'StatPearls [Internet], NBK448129 (act. 2023-04-03)', doi: '', url: 'https://www.ncbi.nlm.nih.gov/books/NBK448129/', revision: { fecha: '2026-10', resultado: 'Sin cambios: el capítulo de StatPearls no se ha actualizado desde el 3 de abril de 2023 (fecha del documento en PubMed, consultada en 2026-10).' }, nota: 'Capítulo de StatPearls (NCBI Bookshelf); PDF aportado por el usuario. La clave lleva el año de la última actualización del capítulo.' },
  'Mehta 2024': { autores: 'Mehta, Karagiannopoulos, Pepin, Ballantyne, Michlovitz, MacDermid, Grewal y Martin', titulo: 'Distal Radius Fracture Rehabilitation: Clinical Practice Guidelines Linked to the International Classification of Functioning, Disability, and Health From the Academy of Orthopaedic Physical Therapy and Academy of Hand and Upper Extremity Physical Therapy of the American Physical Therapy Association', publicacion: 'J Orthop Sports Phys Ther 54(9):CPG1–CPG78', doi: '10.2519/jospt.2024.0301', revision: null, nota: 'Guía de práctica clínica de la APTA; PDF aportado por el usuario, leído (curso clínico e intervenciones, 2026-10). Sin cirugía, yeso 4–6 semanas; operada, protección de días a semanas, movilidad activa en las 3 primeras semanas (A) y fortalecimiento submáximo desde la 2.ª (B); fortalecimiento hacia las 6–8 semanas. Subtipos de radio distal en los tiempos de tejido.' },
  'Mellor 2016': { autores: 'Mellor, Grimaldi, Wajswelner, Hodges, Abbott, Bennell y Vicenzino', titulo: 'Exercise and load modification versus corticosteroid injection versus \'wait and see\' for persistent gluteus medius/minimus tendinopathy (the LEAP trial): a protocol for a randomised clinical trial', publicacion: 'BMC Musculoskelet Disord 17:196', doi: '10.1186/s12891-016-1043-6', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC4852446/', revision: { fecha: '2026-10', resultado: 'Sin cambios: protocolo del ensayo LEAP (ver Mellor 2018); las revisiones posteriores (Wang 2025, Cordeiro 2024) no dan una progresión de ejercicios más detallada.' }, nota: 'Protocolo del ensayo LEAP (texto completo en PMC4852446): tabla 3 con ejercicios y progresión. Dosis de ca4 (cadera).' },
  'Mellor 2018': { autores: 'Mellor, Bennell, Grimaldi, Nicolson, Kasza, Hodges, Wajswelner y Vicenzino', titulo: 'Education plus exercise versus corticosteroid injection use versus a wait and see approach on global outcome and pain from gluteal tendinopathy: prospective, single blinded, randomised clinical trial', publicacion: 'BMJ 361:k1662', doi: '10.1136/bmj.k1662', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC5930290/', revision: { fecha: '2026-10', resultado: 'Sin cambios: PubMed (tendinopatía glútea o dolor trocantéreo con ejercicio o educación desde 2022). El metaanálisis en red de Wang 2025 (J Orthop Surg Res 20:126, 19 ensayos, PMC11783921) sitúa el ejercicio primero para dolor y función, y el de Cordeiro 2024 (Sci Rep 14:3343, PMC10858207) lo encuentra mejor que la intervención mínima (certeza baja) e igual que la infiltración en dolor; ninguno da una pauta mejor que la del LEAP. Leídos en PMC (2026-10).' }, nota: 'Ensayo LEAP, texto completo en PMC5930290. Dosis de ca4 (cadera).' },
  'Mendonça 2016': { autores: 'Mendonça, Ocarino, Bittencourt, Fernandes, Verhagen y Fonseca', titulo: 'The Accuracy of the VISA-P Questionnaire, Single-Leg Decline Squat, and Tendon Pain History to Identify Patellar Tendon Abnormalities in Adult Athletes', publicacion: 'J Orthop Sports Phys Ther 46(8):673–80', doi: '10.2519/jospt.2016.6192', url: 'https://doi.org/10.2519/jospt.2016.6192', revision: { fecha: '2026-10', resultado: 'Cita corregida (PDF del usuario): la muestra son 43 deportistas de competición (86 tendones), no seleccionados por dolor en el tendón; LR+ 4,2 (2,3–7,14) de la sentadilla declinada coincide. Sigue como hallazgo.' }, nota: 'Leído el resumen de PubMed (2026-10). Sentadilla declinada de ro5 (hallazgo: la referencia es la ecografía, no el diagnóstico).' },
