  'Welsch 2018': { autores: 'Welsch, Üçeyler, Klose, Walitt y Häuser', titulo: 'Serotonin and noradrenaline reuptake inhibitors (SNRIs) for fibromyalgia', publicacion: 'Cochrane Database Syst Rev 2018, 2:CD010292', doi: '10.1002/14651858.CD010292.pub2', url: 'https://doi.org/10.1002/14651858.CD010292.pub2', revision: null, nota: 'Revisión Cochrane (18 ensayos, 7903 participantes; evidencia baja o muy baja; estabilizada en 2020). PDF aportado por el usuario (2026-10): leídos enteros el resumen, la tabla de resultados, los antecedentes, los resultados, la discusión y las conclusiones; por encima los métodos, las tablas de estudios y los análisis. Guía de fármacos, familia antidepresivos (docs/farmacologia.md).' },
  'Ferraro 2025': { autores: 'Ferraro, Urquhart, Ferreira, Wewege, Abdel Shaheed, Traeger, Hoving, Visser, McAuley y Cashin', titulo: 'Antidepressants for low back pain and spine-related leg pain', publicacion: 'Cochrane Database Syst Rev 2025, 3:CD001703', doi: '10.1002/14651858.CD001703.pub4', url: 'https://doi.org/10.1002/14651858.CD001703.pub4', revision: null, nota: 'Revisión Cochrane (26 ensayos, búsqueda hasta 2024-11): IRSN, efecto pequeño en el dolor y trivial en la discapacidad; tricíclicos, poco o nada en el dolor; ISRS, insuficiente; sin datos de más de 12 meses ni en mayores. PDF aportado por el usuario (2026-10): leídos enteros el resumen, las tablas de resultados, los antecedentes, los métodos, los resultados, la discusión y las conclusiones; las tablas de estudios y los análisis, solo por búsqueda de efectos adversos (y los análisis 1.26 y 1.27 enteros). Guía de fármacos, familia antidepresivos (docs/farmacologia.md).' },
  'Cashin 2021': { autores: 'Cashin, Folly, Bagg, Wewege, Jones, Ferraro, Leake, Rizzo, Schabrun, Gustin, Day, Williams y McAuley', titulo: 'Efficacy, acceptability, and safety of muscle relaxants for adults with non-specific low back pain: systematic review and meta-analysis', publicacion: 'BMJ 374:n1446', doi: '10.1136/bmj.n1446', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8262447/', revision: null, nota: 'Revisión sistemática y metaanálisis (GRADE): relajantes no benzodiacepínicos, 7,7 puntos menos de dolor sobre 100 a las 2 semanas o menos (certeza muy baja), sin efecto a las 3–13 semanas; benzodiacepinas sin beneficio en el dolor. Texto completo leído entero en PMC con el conector de PubMed (2026-10). Guía de fármacos, familia benzodiacepinas y relajantes musculares (docs/farmacologia.md).' },
  'Wewege 2023': { autores: 'Wewege, Bagg, Jones, Ferraro, Cashin, Rizzo, Leake, Hagstrom, Sharma, McLachlan, Maher, Day, Wand, O’Connell, Nikolakopoulou, Schabrun, Gustin y McAuley', titulo: 'Comparative effectiveness and safety of analgesic medicines for adults with acute non-specific low back pain: systematic review and network meta-analysis', publicacion: 'BMJ 380:e072962', doi: '10.1136/bmj-2022-072962', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10540836/', revision: null, nota: 'Revisión sistemática y metaanálisis en red de los analgésicos en la lumbalgia aguda. Texto completo leído en PMC con el conector de PubMed (2026-10), sin las figuras ni el material suplementario. Guía de fármacos, familia benzodiacepinas y relajantes musculares (docs/farmacologia.md).' },
