  'Mach 2018': { autores: 'Mach, Ray, Wiklund, Corsini, Catapano, Bruckert, De Backer, Hegele, Hovingh, Jacobson, Krauss, Laufs, Leiter, März, Nordestgaard, Raal, Roden, Santos, Stein, Stroes, Thompson, Tokgözoglu, Vladutiu, Gencer, Stock, Ginsberg y Chapman', titulo: 'Adverse effects of statin therapy: perception vs. the evidence – focus on glucose homeostasis, cognitive, renal and hepatic function, haemorrhagic stroke and cataract', publicacion: 'Eur Heart J 39(27):2526–2539', doi: '10.1093/eurheartj/ehy182', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6047411/', revision: null, nota: 'Revisión de consenso de la EAS: diabetes de nueva aparición, cognición, riñón, hígado, efecto nocebo. Texto completo leído entero en PMC con el conector de PubMed (2026-10). Guía de fármacos, familia estatinas (docs/farmacologia.md).' },
  'CTT 2022': { autores: 'Cholesterol Treatment Trialists’ (CTT) Collaboration', titulo: 'Effect of statin therapy on muscle symptoms: an individual participant data meta-analysis of large-scale, randomised, double-blind trials', publicacion: 'Lancet 400(10355):832–845', doi: '10.1016/S0140-6736(22)01545-8', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC7613583/', revision: null, nota: 'Metaanálisis con datos individuales de ensayos ciegos: exceso de dolor o debilidad muscular solo en el primer año (RR 1,07); la estatina explica menos del 10 % de las quejas. Autor colectivo. Texto completo leído entero en PMC con el conector de PubMed (2026-10), sin el apéndice suplementario. Guía de fármacos, familia estatinas (docs/farmacologia.md).' },
  'Epelde 2026': { autores: 'Epelde', titulo: 'Statin-Associated Muscle Symptoms and Myotoxicity: A Clinically Oriented Narrative Review with a Practical Prevention, Evaluation, and Management Algorithm', publicacion: 'Medicina (Kaunas) 62(6):1134', doi: '10.3390/medicina62061134', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC13303987/', revision: null, nota: 'Revisión narrativa de un solo autor: diferenciación de los síntomas, signos de alarma, CK, miopatía anti-HMGCR, ejercicio. Texto completo leído entero en PMC con el conector de PubMed (2026-10). Guía de fármacos, familia estatinas (docs/farmacologia.md).' },
  'Mangone 2024': { autores: 'Mangone, Kwon, Johnson, Wu y Pescatello', titulo: 'The Role of Exercise in Statin-Associated Muscle Symptoms Outcomes: A Systematic Review and Meta-Analysis of Randomized Controlled Trials', publicacion: 'Mayo Clin Proc Innov Qual Outcomes 8(2):131–142', doi: '10.1016/j.mayocpiqo.2024.01.003', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10878792/', revision: null, nota: 'Revisión sistemática y metaanálisis de ensayos con ejercicio y estatina frente a placebo: síntomas, consumo máximo de oxígeno y CK. Texto completo leído entero en PMC con el conector de PubMed (2026-10). Guía de fármacos, familia estatinas (docs/farmacologia.md).' },
  'Yang y Qu 2018': { autores: 'Yang y Qu', titulo: 'The effects of hyperlipidemia on rotator cuff diseases: a systematic review', publicacion: 'J Orthop Surg Res 13(1):204', doi: '10.1186/s13018-018-0912-0', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC6098646/', revision: null, nota: 'Revisión sistemática de estudios observacionales: hiperlipemia, estatinas y manguito rotador; mención de tendinopatía y rotura con estatinas. Texto completo leído entero en PMC con el conector de PubMed (2026-10). Guía de fármacos, familia estatinas (docs/farmacologia.md).' },
