  'Wee 2021': { autores: 'Wee, Chin, Syn, Lee, Ng y Choong', titulo: 'The association between fluoroquinolones and aortic dissection and aortic aneurysms: a systematic review and meta-analysis', publicacion: 'Sci Rep 11(1):11073', doi: '10.1038/s41598-021-90692-8', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8154986/', revision: null, nota: 'Revisión sistemática y metaanálisis. Texto completo leído entero en PMC con el conector de PubMed (2026-10). Las tablas no vinieron en el texto. La OR combinada de disección o aneurisma difiere entre el resumen (1,47) y el texto (1,57): no se cita. Guía de fármacos, familia fluoroquinolonas (docs/farmacologia.md).' },
  'Barberán 2023': { autores: 'Barberán, de la Cuerda, Tejeda González, López Aparicio, Monfort Vinuesa, Ramos Sánchez y Barberán', titulo: 'Safety of fluoroquinolones', publicacion: 'Rev Esp Quimioter 37(2):127–133 (2024; publicado en línea en diciembre de 2023)', doi: '10.37201/req/143.2023', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10945095/', revision: null, nota: 'Revisión narrativa. Texto completo leído entero en PMC con el conector de PubMed (2026-10). En PMC faltan los títulos de sección y la última frase está cortada. La clave lleva el año de la publicación en línea. Guía de fármacos, familia fluoroquinolonas (docs/farmacologia.md).' },
