  'Rusu 2023': { autores: 'Rusu, Munteanu, Arbănași y Uivarosi', titulo: 'Overview of Side-Effects of Antibacterial Fluoroquinolones: New Drugs versus Old Drugs, a Step Forward in the Safety Profile?', publicacion: 'Pharmaceutics 15(3):804', doi: '10.3390/pharmaceutics15030804', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10056716/', revision: null, nota: 'Revisión narrativa. Texto completo leído entero en PMC con el conector de PubMed (2026-10). Las figuras y algunas tablas no vinieron en el texto. Las pautas de protección y carga del tendón las da citando otra fuente que no nombra en el texto. Guía de fármacos, familia fluoroquinolonas (docs/farmacologia.md).' },
  'Duman 2025': { autores: 'Duman, Müller-Deubert, Pattappa, Stratos, Sieber, Clausen-Schaumann, Sarafian, Shukunami, Rudert y Docheva', titulo: 'Fluoroquinolone-Mediated Tendinopathy and Tendon Rupture', publicacion: 'Pharmaceuticals (Basel) 18(2):184', doi: '10.3390/ph18020184', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC11858458/', revision: null, nota: 'Revisión narrativa con mucho contenido preclínico. Texto completo leído entero en PMC con el conector de PubMed (2026-10). Las tablas y figuras no vinieron en el texto. Guía de fármacos, familia fluoroquinolonas (docs/farmacologia.md).' },
  'Lewis y Cook 2014': { autores: 'Lewis y Cook', titulo: 'Fluoroquinolones and tendinopathy: a guide for athletes and sports clinicians and a systematic review of the literature', publicacion: 'J Athl Train 49(3):422–427', doi: '10.4085/1062-6050-49.2.09', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC4080593/', revision: null, nota: 'Revisión sistemática para deportistas y clínicos del deporte. En PMC solo el resumen; PDF aportado por el usuario y leído entero (2026-10). Anterior a 2015: se admite por ser la única fuente leída sobre rehabilitación y deportistas. La vigilancia tras el tratamiento es de 1 mes en su tabla 2 y de al menos 6 meses en el texto. Guía de fármacos, familia fluoroquinolonas (docs/farmacologia.md).' },
  'EMA 2018': { autores: 'European Medicines Agency', titulo: 'Disabling and potentially permanent side effects lead to suspension or restrictions of quinolone and fluoroquinolone antibiotics', publicacion: 'EMA/795349/2018, 16 de noviembre de 2018', doi: '', url: 'https://www.ema.europa.eu/en/news/disabling-potentially-permanent-side-effects-lead-suspension-or-restrictions-quinolone-fluoroquinolone-antibiotics', revision: null, nota: 'Nota de la revisión del artículo 31 (PRAC, 4 de octubre de 2018), con información para pacientes y profesionales. PDF aportado por el usuario y leído entero (2026-10). Guía de fármacos, familia fluoroquinolonas (docs/farmacologia.md).' },
  'AEMPS 2023': { autores: 'Agencia Española de Medicamentos y Productos Sanitarios', titulo: 'Fluoroquinolonas de administración sistémica o inhalada: recordatorio sobre las restricciones de uso', publicacion: 'Nota informativa MUH(FV), 07/2023, 23 de octubre de 2023', doi: '', url: 'https://www.aemps.gob.es/informa/fluoroquinolonas-de-administracion-sistemica-o-inhalada-recordatorio-sobre-las-restricciones-de-uso/', revision: null, nota: 'Recuerda la nota MUH (FV), 14/2018. PDF aportado por el usuario y leído entero (2026-10). Guía de fármacos, familia fluoroquinolonas (docs/farmacologia.md).' },
  'Thai 2023': { autores: 'Thai, Salisbury y Zito', titulo: 'Ciprofloxacin', publicacion: 'StatPearls [Internet], NBK535454 (act. 2023-08-28)', doi: '', url: 'https://www.ncbi.nlm.nih.gov/books/NBK535454/', revision: null, nota: 'Capítulo de StatPearls (NCBI Bookshelf); PDF aportado por el usuario y leído entero (2026-10). La clave lleva el año de la última actualización del capítulo. Guía de fármacos, familia fluoroquinolonas (docs/farmacologia.md).' },
