  'Podder 2024': { autores: 'Podder, Patel y Sadiq', titulo: 'Levofloxacin', publicacion: 'StatPearls [Internet], NBK545180 (act. 2024-03-01)', doi: '', url: 'https://www.ncbi.nlm.nih.gov/books/NBK545180/', revision: null, nota: 'Capítulo de StatPearls (NCBI Bookshelf); PDF aportado por el usuario y leído entero (2026-10). La clave lleva el año de la última actualización del capítulo. Guía de fármacos, familia fluoroquinolonas (docs/farmacologia.md).' },
  'Levy 2024': { autores: 'Levy, Sharma, Farci y Le', titulo: 'Aortic Dissection', publicacion: 'StatPearls [Internet], NBK441963 (act. 2024-10-06)', doi: '', url: 'https://www.ncbi.nlm.nih.gov/books/NBK441963/', revision: null, nota: 'Capítulo de StatPearls (NCBI Bookshelf); PDF aportado por el usuario y leído entero (2026-10). La clave lleva el año de la última actualización del capítulo. No menciona las fluoroquinolonas: se usa para cómo se presenta la disección y cuándo es urgente. Guía de fármacos, familia fluoroquinolonas (docs/farmacologia.md).' },
  'Mitchell 2025': { autores: 'Mitchell, Davison, Parfitt y Eston', titulo: 'Effect of β-blockade on measures and reproducibility of heart rate, oxygen uptake and work rate across repeated bouts of short-duration, RPE-regulated exercise', publicacion: 'Eur J Appl Physiol 125(11):3247–3257', doi: '10.1007/s00421-025-05818-x', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC12528277/', revision: null, nota: 'Ensayo cruzado, doble ciego, con placebo (metoprolol 100 mg en una sola toma; 13 adultos jóvenes sanos). Texto completo leído entero en PMC con el conector de PubMed (2026-10), sin las tablas 1–3 ni el material en línea. Es un estudio primario: se admite porque no se halló en PMC ninguna revisión sobre el esfuerzo percibido con betabloqueantes. Guía de fármacos, familia betabloqueantes (docs/farmacologia.md).' },
  'Hansen 2022': { autores: 'Hansen, Abreu, Ambrosetti, Cornelissen, Gevaert, Kemps, Laukkanen, Pedretti, Simonenko y Wilhelm', titulo: 'Exercise intensity assessment and prescription in cardiovascular rehabilitation and beyond: why and how: a position statement from the Secondary Prevention and Rehabilitation Section of the European Association of Preventive Cardiology', publicacion: 'Eur J Prev Cardiol 29(1):230–245', doi: '10.1093/eurjpc/zwab007', url: 'https://doi.org/10.1093/eurjpc/zwab007', revision: null, nota: 'Posicionamiento de la EAPC. No está en PMC; PDF aportado por el usuario y leído entero (2026-10), salvo el resumen gráfico (escala OMNI-RES), que no se extrajo. Guía de fármacos, familia betabloqueantes (docs/farmacologia.md).' },
  'Ez Eddin 2025': { autores: 'Ez Eddin, Preyra, Ahmadi et al. (último autor, Muanda)', titulo: 'β-Blockers and risk of neuropsychiatric disorders: a systematic review and meta-analysis', publicacion: 'Br J Clin Pharmacol 91(2):325–337', doi: '10.1111/bcp.16361', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC11773113/', revision: null, nota: 'Revisión sistemática y metaanálisis. Texto completo leído entero en PMC con el conector de PubMed (2026-10), sin el material suplementario; los forest plots, solo por sus pies. Publicado en línea en 2024; la clave lleva el año del número. El texto y el pie de la figura 8 no coinciden en el IC del insomnio con propranolol, ni el texto y la figura 9 en el de las pesadillas: no se citan esas cifras. Guía de fármacos, familia betabloqueantes (docs/farmacologia.md).' },
  'Ham 2017': { autores: 'Ham, van Dijk, Swart et al. (autora de correspondencia, van der Velde)', titulo: 'Beta-blocker use and fall risk in older individuals: Original results from two studies with meta-analysis', publicacion: 'Br J Clin Pharmacol 83:2292–2302', doi: '10.1111/bcp.13328', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC5595938/', revision: null, nota: 'Dos cohortes (Rotterdam y B-PROOF, 55 años o más) con metaanálisis. En PMC el conector no devolvió el texto; PDF aportado por el usuario y leído entero (2026-10). El texto y la tabla 3 dan al revés los HR de lipófilos y no lipófilos: no se citan. Guía de fármacos, familia betabloqueantes (docs/farmacologia.md).' },
  'Marko y Pawliczak 2025': { autores: 'Marko y Pawliczak', titulo: 'An updated insight into the effect of β-adrenergic receptor antagonists (β-blockers) on respiratory function in asthma patients: a systematic review and meta-analysis', publicacion: 'Front Physiol 16:1582740', doi: '10.3389/fphys.2025.1582740', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC12331582/', revision: null, nota: 'Revisión sistemática y metaanálisis. Texto completo leído entero en PMC con el conector de PubMed (2026-10); las figuras, solo por su texto alternativo. Se contradice en la clasificación del carvedilol y en la p del FEV1 con cardioselectivos (0,08 en el texto, 0,008 en la tabla 4): no se citan. Guía de fármacos, familia betabloqueantes (docs/farmacologia.md).' },
  'Dos Santos 2024': { autores: 'Dos Santos, Camelier, Menezes et al.', titulo: 'Effects of the Use of Beta-Blockers on Chronic Obstructive Pulmonary Disease Associated with Cardiovascular Comorbidities: Systematic Review and Meta-analysis', publicacion: 'Tuberc Respir Dis (Seoul) 87(3):261–281', doi: '10.4046/trd.2024.0013', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC11222090/', revision: null, nota: 'Revisión sistemática y metaanálisis. Texto completo leído entero en PMC con el conector de PubMed (2026-10), sin tablas ni forest plots. Los resultados no hallan relación con la gravedad de la EPOC y la discusión habla de menos función pulmonar: no se cita ese punto. Guía de fármacos, familia betabloqueantes (docs/farmacologia.md).' },
  'Carnovale 2023': { autores: 'Carnovale, Perrotta, Baldelli et al. (último autor, Pozzi)', titulo: 'Antihypertensive drugs and brain function: mechanisms underlying therapeutically beneficial and harmful neuropsychiatric effects', publicacion: 'Cardiovasc Res 119(3):647–667', doi: '10.1093/cvr/cvac110', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10153433/', revision: null, nota: 'Revisión. Texto completo leído entero en PMC con el conector de PubMed (2026-10), sin la tabla suplementaria de estudios clínicos ni los colores de la tabla 2. Guía de fármacos, familia betabloqueantes (docs/farmacologia.md).' },
  'Thompson 2026': { autores: 'Thompson, Alaeiilkhchi, McCarthy et al. (último autor, Goyal)', titulo: 'Beta-Blocker Discontinuation After Myocardial Infarction: A Systematic Review and Meta-Analysis', publicacion: 'JACC Adv 5(6 Pt 2):102840', doi: '10.1016/j.jacadv.2026.102840', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC13308238/', revision: null, nota: 'Revisión sistemática y metaanálisis de la retirada planificada, no de la brusca. Texto completo leído entero en PMC con el conector de PubMed (2026-10), sin el material suplementario. Guía de fármacos, familia betabloqueantes (docs/farmacologia.md).' },
  'Dar y Jacob 2024': { autores: 'Dar y Jacob', titulo: 'Beta Blockers in Contemporary Cardiology: Is It Better to Cast Them Out?', publicacion: 'Korean Circ J 54(4):165–171', doi: '10.4070/kcj.2023.0209', url: 'https://pmc.ncbi.nlm.nih.gov/articles/PMC11040266/', revision: null, nota: 'Revisión narrativa de opinión. Texto completo leído entero en PMC con el conector de PubMed (2026-10). Guía de fármacos, familia betabloqueantes (docs/farmacologia.md).' },
